#include "engine/script/ScriptRuntimeHost.hpp"
#include "engine/script/ScriptFunctionRegistry.hpp"
#include "engine/scene/SceneAccessibility.hpp"
#include "engine/scene/SceneVideoPlayers.hpp"
#include <algorithm>
namespace kb::script {
namespace {
using Pins=std::vector<ScriptFunctionPin>;
const ScriptValue& Arg(std::span<const ScriptFunctionArgument> args,std::string_view name){static const ScriptValue empty;for(const auto& a:args)if(a.name==name)return a.value;return empty;}
ScriptFunctionCallResult Error(std::string error){return {.executed=false,.outputs={},.errors={std::move(error)}};}
ScriptFunctionCallResult Flag(std::string name,bool value){return {.executed=true,.outputs={{std::move(name),ScriptValue{value}}}};}
ScriptValue Entity(kb::scene::SceneEntity entity){return ScriptValue{entity.Id(),ScriptValueType::Entity};}
}
bool RegisterUIMediaApi(ScriptRuntimeHost& host){
    bool ok=true;
    auto add=[&](const char* name,Pins in,Pins out,auto callback){ScriptFunctionDesc f;f.signature.name=name;f.signature.description="Runtime UI media and semantic accessibility through the shared scene backend. See RuntimeUI topic for platform and format limits.";f.signature.inputs=std::move(in);f.signature.outputs=std::move(out);f.callback=callback;ok=host.RegisterFunction(std::move(f))&&ok;};
    const Pins target{{"entity",ScriptValueType::Entity,true}},flag{{"succeeded",ScriptValueType::Bool,true}};
    add("Accessibility.Node",{{"index",ScriptValueType::Int,true}},{{"count",ScriptValueType::Int,true},{"entity",ScriptValueType::Entity,true},{"parent",ScriptValueType::Entity,true},{"name",ScriptValueType::String,true},{"value",ScriptValueType::String,true},{"hint",ScriptValueType::String,true},{"role",ScriptValueType::Int,true},{"focused",ScriptValueType::Bool,true},{"enabled",ScriptValueType::Bool,true},{"password",ScriptValueType::Bool,true}},[](const auto& c,auto a)->ScriptFunctionCallResult{
        if(!c.scene)return Error("scene is unavailable");const auto tree=kb::scene::SceneAccessibility::Read(*c.scene);if(!tree.error.empty())return Error(tree.error);const int i=Arg(a,"index").AsInt();kb::scene::UIAccessibilityNode n;if(i>=0&&static_cast<std::size_t>(i)<tree.nodes.size())n=tree.nodes[static_cast<std::size_t>(i)];return {.executed=true,.outputs={{"count",ScriptValue{static_cast<int>(tree.nodes.size())}},{"entity",Entity(n.entity)},{"parent",Entity(n.parent)},{"name",ScriptValue{n.name}},{"value",ScriptValue{n.value}},{"hint",ScriptValue{n.hint}},{"role",ScriptValue{static_cast<int>(n.role)}},{"focused",ScriptValue{n.focused}},{"enabled",ScriptValue{n.enabled}},{"password",ScriptValue{n.password}}}};
    });
    add("Accessibility.Focus",target,flag,[](const auto& c,auto a){return c.scene?Flag("succeeded",kb::scene::SceneAccessibility::Focus(*c.scene,kb::scene::SceneEntity{Arg(a,"entity").AsUInt64()})):Error("scene is unavailable");});
    add("Accessibility.Invoke",target,flag,[](const auto& c,auto a){return c.scene?Flag("succeeded",kb::scene::SceneAccessibility::Invoke(*c.scene,kb::scene::SceneEntity{Arg(a,"entity").AsUInt64()})):Error("scene is unavailable");});
    add("Accessibility.SetValue",{{"entity",ScriptValueType::Entity,true},{"value",ScriptValueType::String,true}},flag,[](const auto& c,auto a){std::string e;if(!c.scene)return Error("scene is unavailable");return kb::scene::SceneAccessibility::SetValue(*c.scene,kb::scene::SceneEntity{Arg(a,"entity").AsUInt64()},Arg(a,"value").AsString(),e)?Flag("succeeded",true):Error(e);});
    add("Accessibility.Speak",{},{{"id",ScriptValueType::Int64,true}},[](const auto& c,auto)->ScriptFunctionCallResult{if(!c.scene)return Error("scene is unavailable");std::string e;const auto id=kb::scene::SceneAccessibility::SpeakFocused(*c.scene,e);return id?ScriptFunctionCallResult{.executed=true,.outputs={{"id",ScriptValue{static_cast<std::int64_t>(id)}}}}:Error(e);});
    add("Accessibility.ScreenReader",{{"enabled",ScriptValueType::Bool,true}},flag,[](const auto& c,auto a){if(!c.scene)return Error("scene is unavailable");kb::scene::SceneAccessibility::SetScreenReaderEnabled(*c.scene,Arg(a,"enabled").AsBool());return Flag("succeeded",true);});
    add("Accessibility.Speech",{{"id",ScriptValueType::Int64,true}},{{"ready",ScriptValueType::Bool,true},{"succeeded",ScriptValueType::Bool,true},{"text",ScriptValueType::String,true},{"error",ScriptValueType::String,true}},[](const auto& c,auto a)->ScriptFunctionCallResult{if(!c.scene)return Error("scene is unavailable");const auto r=kb::scene::SceneAccessibility::ReadSpeech(*c.scene,static_cast<std::uint64_t>(Arg(a,"id").AsInt64()));return {.executed=true,.outputs={{"ready",ScriptValue{r.ready}},{"succeeded",ScriptValue{r.succeeded}},{"text",ScriptValue{r.text}},{"error",ScriptValue{r.error}}}};});
    add("UIVideo.Play",{{"entity",ScriptValueType::Entity,true},{"asset",ScriptValueType::String,true},{"loop",ScriptValueType::Bool,false}},flag,[](const auto& c,auto a){if(!c.scene)return Error("scene is unavailable");std::string e;return kb::scene::SceneVideoPlayers::Play(*c.scene,kb::scene::SceneEntity{Arg(a,"entity").AsUInt64()},Arg(a,"asset").AsString(),Arg(a,"loop").AsBool(),e)?Flag("succeeded",true):Error(e);});
    add("UIVideo.Info",target,{{"available",ScriptValueType::Bool,true},{"playing",ScriptValueType::Bool,true},{"paused",ScriptValueType::Bool,true},{"ended",ScriptValueType::Bool,true},{"audioSeconds",ScriptValueType::Double,true},{"videoSeconds",ScriptValueType::Double,true},{"durationSeconds",ScriptValueType::Double,true},{"revision",ScriptValueType::Int64,true},{"error",ScriptValueType::String,true}},[](const auto& c,auto a)->ScriptFunctionCallResult{if(!c.scene)return Error("scene is unavailable");const auto r=kb::scene::SceneVideoPlayers::Read(*c.scene,kb::scene::SceneEntity{Arg(a,"entity").AsUInt64()});return {.executed=true,.outputs={{"available",ScriptValue{r.available}},{"playing",ScriptValue{r.playing}},{"paused",ScriptValue{r.paused}},{"ended",ScriptValue{r.ended}},{"audioSeconds",ScriptValue{r.audioSeconds}},{"videoSeconds",ScriptValue{r.videoSeconds}},{"durationSeconds",ScriptValue{r.durationSeconds}},{"revision",ScriptValue{static_cast<std::int64_t>(r.frameRevision)}},{"error",ScriptValue{r.error}}}};});
    add("UIVideo.Pause",target,flag,[](const auto& c,auto a){return c.scene?Flag("succeeded",kb::scene::SceneVideoPlayers::Pause(*c.scene,kb::scene::SceneEntity{Arg(a,"entity").AsUInt64()})):Error("scene is unavailable");});
    add("UIVideo.Resume",target,flag,[](const auto& c,auto a){return c.scene?Flag("succeeded",kb::scene::SceneVideoPlayers::Resume(*c.scene,kb::scene::SceneEntity{Arg(a,"entity").AsUInt64()})):Error("scene is unavailable");});
    add("UIVideo.Seek",{{"entity",ScriptValueType::Entity,true},{"seconds",ScriptValueType::Double,true}},flag,[](const auto& c,auto a){if(!c.scene)return Error("scene is unavailable");std::string e;return kb::scene::SceneVideoPlayers::Seek(*c.scene,kb::scene::SceneEntity{Arg(a,"entity").AsUInt64()},Arg(a,"seconds").AsDouble(),e)?Flag("succeeded",true):Error(e);});
    add("UIVideo.Stop",target,flag,[](const auto& c,auto a){if(!c.scene)return Error("scene is unavailable");kb::scene::SceneVideoPlayers::Stop(*c.scene,kb::scene::SceneEntity{Arg(a,"entity").AsUInt64()});return Flag("succeeded",true);});return ok;
}
}
